sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
	c.clockIn = function () {
    c.data.action = 'clock_in';
    c.server.update().then(function (response) {
			setTimeout(function() {
        window.location.reload();
      }, 3000);
    });
  };
  c.clockOut = function () {
    c.data.action = 'clock_out';
    c.server.update().then(function (response) {
			setTimeout(function() {
        window.location.reload();
      }, 3000);
    });
  };
};

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
	data.ok = true;
  data.message = '';
  data.loading = false;

  var ATTENDANCE_TABLE = 'x_594089_employe_0_attendance';
	var EMPLOYEE_TABLE = 'x_594089_employe_0_hr_employee';
  // Get the current user's username from the sys_user table
  var userName = gs.getUserName();
	gs.info('userName'+ userName);
	var email = gs.getUser().getEmail();
	gs.info('email'+ email);
  var employeeSysId = null;

	//First, find the employee record associated with the current user's username
  var grEmployee = new GlideRecord(EMPLOYEE_TABLE);
  grEmployee.addQuery('number', userName); 
	grEmployee.addQuery('email', email); 
  grEmployee.query();
  if (grEmployee.next()) {
    employeeSysId = grEmployee.sys_id;
		gs.info('employeeSysId'+ employeeSysId)
  }

  // helper: get (or create) today's attendance record
  function getTodaysRecord(empId) {
		if (!empId) {
      return null;
    }
    //var today = new GlideDateTime(); // date-only in instance TZ
		//today.setDisplayValue(today.nowDate() + ' 00:05:00');
		var today1 = new GlideDateTime();
		//gs.info('today'+ today1)
		var datePart = today1.getLocalDate().getValue(); // yyyy-MM-dd
		// Append custom time to the date
		var today = new GlideDateTime(datePart + '03:31:26');
		gs.info('today'+ today)
		gs.info('getTodaysRecord empId '+ empId);
    var gr = new GlideRecord(ATTENDANCE_TABLE);
    gr.addQuery('employee', empId);
   // gr.addQuery('sys_created_on', today); // works if u_date is Date type
    gr.query();
    if (gr.next()) return gr;
    return null;
  }

  // on initial load, fetch today's record to show in UI
  var currentRec = getTodaysRecord(employeeSysId);
	//gs.info('currentRec1' + currentRec);

	// If no employee record is found, stop here and show an error
  if (!employeeSysId) {
    data.ok = false;
    data.message = 'No employee record found for this user. Please contact support.';
    return;
  }

  // handle button actions
  if (input && input.action) {
    data.loading = true;

    if (input.action === 'clock_in') {
			gs.info('input.action' + input.action);
		gs.info('currentRec in if ' + currentRec);
      if (currentRec && currentRec.in_time) {
        data.ok = false;
        data.message = 'You have already clocked in.';
      } else {
        var nowIn = new GlideDateTime();
				gs.info('currentRec' + currentRec);
 				// This is the simplified logic: it now assumes the record exists and updates it directly.
        if (currentRec) {
          currentRec.in_time = nowIn;
          currentRec.status = 'present';
          currentRec.update();
          data.ok = true;
          data.message = 'Clocked in at ' + nowIn.getDisplayValue();
        } else {
          data.ok = false;
          data.message = 'No pending record found for today. Please contact support.';
        }
      }
    }
    // Logic for the 'clock_out' action
    if (input.action === 'clock_out') {
      if (!currentRec || !currentRec.in_time) {
        data.ok = false;
        data.message = 'You have not clocked in today.';
      } else if (currentRec.out_time) {
        data.ok = false;
        data.message = 'You have already clocked out.';
      } else {
        var nowOut = new GlideDateTime();
        currentRec.out_time = nowOut;
        currentRec.status = 'Completed';

       // if (currentRec.isValidField('duration_minutes') && currentRec.in_time) {
         // var diffMS = GlideDateTime.subtract(nowOut, currentRec.in_time).getNumericValue();
        //  var mins = Math.round(diffMS / 60000);
        //  currentRec.duration_minutes = mins;
        //}

        currentRec.update();

        data.ok = true;
        data.message = 'Clocked out at ' + nowOut.getDisplayValue();
      }
    }
  }

  // Refresh the data object with the latest record information for the UI
  currentRec = getTodaysRecord(employeeSysId);
  if (currentRec) {
    data.record = {
      sys_id: currentRec.getUniqueValue(),
      date: currentRec.login_date ? (currentRec.login_date.getDisplayValue ? currentRec.login_date.getDisplayValue() : currentRec.login_date + '') : '',
      time_in: currentRec.in_time ? currentRec.in_time.getDisplayValue() : '',
      time_out: currentRec.out_time ? currentRec.out_time.getDisplayValue() : '',
      status: currentRec.status + ''
    };
  }
})();
